// Detect theme from storage, set on container INSIDE shadow
const data = await getStorage(STORAGE_KEYS.THEME_MODE);
const resolved = mode === 'system' ? (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') : (mode ?? 'dark');
this.container.setAttribute('data-theme', resolved);
// [data-theme="dark"] now matches container → dark tokens cascade

// Listen to storage.onChanged + matchMedia change for real-time switch
onStorageChanged((changes) => { if (THEME_MODE in changes) refreshTheme(); });
mql.addEventListener('change', () => refreshTheme());
// cleanup in destroy(): removeOnStorageChangedListener + mql.removeEventListener

